<?php
namespace Tests\Feature;
use App\Enums\UserRole; use App\Models\Service; use App\Models\User; use Carbon\CarbonImmutable; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class ScheduleTest extends TestCase { use RefreshDatabase; public function test_slots_exclude_blocked_time(): void { $u=User::create(['name'=>'P','email'=>'p@test.com','password'=>'password123','role'=>UserRole::Provider]);$p=$u->provider()->create(['timezone'=>'UTC','is_active'=>true]);$s=Service::create(['name'=>'Consult','duration_minutes'=>30,'is_active'=>true]);$p->services()->attach($s->id,['price'=>100,'is_active'=>true]);$date=CarbonImmutable::now('UTC')->addDays(3)->startOfDay();$p->availabilities()->create(['day_of_week'=>$date->dayOfWeek,'start_time'=>'09:00','end_time'=>'11:00']);$p->blockedTimes()->create(['starts_at'=>$date->setTime(9,30),'ends_at'=>$date->setTime(10,0),'reason'=>'Meeting']);$r=$this->getJson('/api/providers/'.$p->id.'/slots?date='.$date->format('Y-m-d').'&service_id='.$s->id)->assertOk();$starts=collect($r->json('data'))->pluck('local_start');$this->assertFalse($starts->contains($date->format('Y-m-d').' 09:30'));$this->assertTrue($starts->contains($date->format('Y-m-d').' 10:00')); } }
